<template>
  <div class="museum-site-menu" :class="{'is-open':open}" :data-exhibition-keyboard="open?'native':null" @pointerenter="pointerEnter" @pointerleave="pointerLeave" @focusout="focusOut" @keydown="onKey">
    <button ref="trigger" class="museum-site-trigger" type="button" aria-label="Site navigation" :aria-expanded="open" @click="toggle">H.W.<svg viewBox="0 0 12 12" aria-hidden="true"><path d="m3 4 3 3 3-3"/></svg></button>
    <transition name="museum-site"><nav v-if="open" class="museum-site-links" aria-label="Henry’s site"><a v-for="item in items" :key="item.path" :href="`#${item.path}`" @click="navigate($event,item.path)"><span>{{ item.label }}</span></a></nav></transition>
  </div>
</template>
<script>
export default {
  emits:['navigate'], data:()=>({open:false,pinned:false,keyboardOpen:false}),
  computed:{items(){return[{path:'/home',label:'Home'},{path:'/education',label:'Study'},{path:'/experience',label:'Work'},{path:'/research',label:'Research'},{path:'/projects',label:'Builds'},{path:'/fragments',label:'Fragments'}];}},
  mounted(){this._outside=e=>{if(!this.$el.contains(e.target))this.close();};document.addEventListener('pointerdown',this._outside,true);},
  beforeUnmount(){clearTimeout(this._leaveTimer);document.removeEventListener('pointerdown',this._outside,true);},
  methods:{
    close(){clearTimeout(this._leaveTimer);this.open=false;this.pinned=false;this.keyboardOpen=false;},
    pointerEnter(event){if(event.pointerType!=='mouse'||!matchMedia('(hover:hover) and (pointer:fine)').matches)return;clearTimeout(this._leaveTimer);this.open=true;},
    pointerLeave(){if(this.pinned||(this.keyboardOpen&&this.$el.contains(document.activeElement)))return;clearTimeout(this._leaveTimer);this._leaveTimer=setTimeout(()=>this.close(),180);},
    toggle(){if(this.pinned){this.close();return;}clearTimeout(this._leaveTimer);this.open=true;this.pinned=true;this.keyboardOpen=false;},
    focusOut(event){if(!this.$el.contains(event.relatedTarget))this.close();},
    onKey(event){
      if(event.key==='Escape'&&this.open){event.preventDefault();event.stopPropagation();this.close();this.$refs.trigger.focus({preventScroll:true});return;}
      if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;
      if(!this.open&&event.target!==this.$refs.trigger)return;
      event.preventDefault();event.stopPropagation();clearTimeout(this._leaveTimer);this.open=true;this.keyboardOpen=true;
      this.$nextTick(()=>{const links=[...this.$el.querySelectorAll('nav a')],current=links.indexOf(document.activeElement);const index=event.key==='Home'?0:event.key==='End'?links.length-1:event.key==='ArrowDown'?(current+1)%links.length:current<=0?links.length-1:current-1;links[index]?.focus({preventScroll:true});});
    },
    navigate(event,path){if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();this.close();this.$emit('navigate',path);},
  },
};
</script>
<style scoped>
.museum-site-menu { position:relative; flex:none; }
.museum-site-trigger { display:flex; align-items:center; gap:9px; border:0; padding:0; min-height:44px; background:none; color:inherit; font:27px 'Quattrocento Sans',sans-serif; cursor:var(--site-interactive-cursor,pointer); }
.museum-site-trigger svg { width:11px; height:11px; fill:none; stroke:currentColor; stroke-width:1; opacity:.5; transition:transform 200ms ease,opacity 200ms ease; }
.is-open .museum-site-trigger svg { transform:rotate(180deg);opacity:.85; }
.museum-site-links { position:absolute; top:calc(100% + 10px); left:-12px; width:212px; padding:10px; z-index:30; border:1px solid color-mix(in srgb,var(--ex-border,#d5d4c9) 65%,transparent); border-radius:3px; background:color-mix(in srgb,var(--ex-paper,#f5f3ec) 96%,transparent); color:var(--ex-ink,#34372f); box-shadow:0 12px 36px #10130d14,0 2px 6px #10130d08; backdrop-filter:blur(14px); transform-origin:24px 0; }
.museum-site-links::before { content:'';position:absolute;left:0;right:0;top:-12px;height:12px; }
.museum-site-links a { position:relative;display:flex;align-items:center;min-height:40px;padding:0 14px;color:var(--ex-muted,#73766b);text-decoration:none;font:16px 'Quattrocento Sans',sans-serif;transition:color 150ms ease,background-color 150ms ease; }
.museum-site-links a span { transition:transform 160ms ease; }
.museum-site-links a:hover,.museum-site-links a:focus-visible { color:var(--ex-ink,#34372f);background:color-mix(in srgb,currentColor 5%,transparent); }
.museum-site-links a:hover span { transform:translateX(2px); }
.museum-site-links a:focus-visible { outline:1px solid color-mix(in srgb,currentColor 45%,transparent);outline-offset:-1px; }
.museum-site-enter-active { transition:opacity 180ms ease,transform 220ms cubic-bezier(.22,1,.36,1); }
.museum-site-leave-active { transition:opacity 140ms ease,transform 140ms ease;pointer-events:none; }
.museum-site-enter-from,.museum-site-leave-to { opacity:0;transform:translateY(-5px) scale(.985); }
@media(max-width:767px) { .museum-site-trigger { font-size:23px;gap:5px; }.museum-site-links{left:0;width:196px;}.museum-site-links a{min-height:44px;} }
@media(max-height:480px) { .museum-site-links { max-height:calc(100dvh - 78px);overflow-y:auto; } }
@media(prefers-reduced-motion:reduce) { .museum-site-enter-active,.museum-site-leave-active,.museum-site-trigger svg,.museum-site-links a span{transition:none;}.museum-site-enter-from,.museum-site-leave-to,.museum-site-links a:hover span{transform:none;} }
</style>
